 for(const b of this.flowers)this.addBox([b.x,10.8,b.z],[4.5,21.6,4.5]);
 field.updateMatrixWorld(true);field.userData.hives.forEach((group,index)=>{const body=new C.Body({type:C.Body.KINEMATIC,position:cv(group.position),collisionFilterGroup:1,collisionFilterMask:2});body.quaternion.copy(cq(group.quaternion));const cells=group.children.filter(o=>/upright hive cell/.test(o.name));const hive={group,body,index,angle:group.rotation.x,targetAngle:group.rotation.x,initialAngle:group.rotation.x,cells,counts:cells.map(()=>({pollen:0,nectar:0,load:0})),tilts:0};for(const cell of cells)this.cellShapes(body,cell);this.world.addBody(body);this.hives.push(hive);});
